use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Compute the eligibility and assignment of each local."] fn coroutine_saved_local_eligibility < VariantIdx : Idx , FieldIdx : Idx , LocalIdx : Idx > (nb_locals : usize , variant_fields : & IndexSlice < VariantIdx , IndexVec < FieldIdx , LocalIdx > > , storage_conflicts : & BitMatrix < LocalIdx , LocalIdx > ,) -> (DenseBitSet < LocalIdx > , IndexVec < LocalIdx , SavedLocalEligibility < VariantIdx , FieldIdx > >) { use SavedLocalEligibility :: * ; let mut assignments : IndexVec < LocalIdx , _ > = IndexVec :: from_elem_n (Unassigned , nb_locals) ; let mut ineligible_locals = DenseBitSet :: new_empty (nb_locals) ; for (variant_index , fields) in variant_fields . iter_enumerated () { for local in fields { match assignments [* local] { Unassigned => { assignments [* local] = Assigned (variant_index) ; } Assigned (idx) => { trace ! ("removing local {:?} in >1 variant ({:?}, {:?})" , local , variant_index , idx) ; ineligible_locals . insert (* local) ; assignments [* local] = Ineligible (None) ; } Ineligible (_) => { } } } } for local_a in storage_conflicts . rows () { let conflicts_a = storage_conflicts . count (local_a) ; if ineligible_locals . contains (local_a) { continue ; } for local_b in storage_conflicts . iter (local_a) { if ineligible_locals . contains (local_b) || assignments [local_a] == assignments [local_b] { continue ; } let conflicts_b = storage_conflicts . count (local_b) ; let (remove , other) = if conflicts_a > conflicts_b { (local_a , local_b) } else { (local_b , local_a) } ; ineligible_locals . insert (remove) ; assignments [remove] = Ineligible (None) ; trace ! ("removing local {:?} due to conflict with {:?}" , remove , other) ; } } { let mut used_variants = DenseBitSet :: new_empty (variant_fields . len ()) ; for assignment in & assignments { if let Assigned (idx) = assignment { used_variants . insert (* idx) ; } } if used_variants . count () < 2 { for assignment in assignments . iter_mut () { * assignment = Ineligible (None) ; } ineligible_locals . insert_all () ; } } { for (idx , local) in ineligible_locals . iter () . enumerate () { assignments [local] = Ineligible (Some (FieldIdx :: new (idx))) ; } } debug ! ("coroutine saved local assignments: {:?}" , assignments) ; (ineligible_locals , assignments) }